package repository

import (
	"sync"

	"benchmark.local/iam/internal/domain"
)

// UserRepository is a concurrency-safe in-memory store for users. The email
// index contains normalized addresses and is maintained under the same lock
// as users, so an email cannot be claimed by two users.
type UserRepository struct {
	mu         sync.RWMutex
	users      map[domain.UserID]domain.User
	emailIndex map[string]domain.UserID
}

// NewUserRepository creates an empty user repository.
func NewUserRepository() *UserRepository {
	return &UserRepository{
		users:      make(map[domain.UserID]domain.User),
		emailIndex: make(map[string]domain.UserID),
	}
}

// Create stores a user and reserves its normalized email address.
func (r *UserRepository) Create(user domain.User) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "user repository is nil")
	}
	if user.ID == "" {
		return domain.NewError(domain.ErrorInvalid, "user id and email are required")
	}
	key, err := domain.ValidateEmail(user.Email)
	if err != nil {
		return err
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.users[user.ID]; exists {
		return domain.NewError(domain.ErrorConflict, "user already exists")
	}
	if _, exists := r.emailIndex[key]; exists {
		return domain.NewError(domain.ErrorConflict, "email already exists")
	}
	// Store both the aggregate and its credential byte slices detached from the
	// caller. This keeps later caller mutations from bypassing repository lock.
	user.Email = key
	r.users[user.ID] = cloneUser(user)
	r.emailIndex[key] = user.ID
	return nil
}

// GetByID returns a detached copy of the user with the supplied ID.
func (r *UserRepository) GetByID(id domain.UserID) (domain.User, error) {
	if r == nil {
		return domain.User{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	user, ok := r.users[id]
	if !ok {
		return domain.User{}, domain.ErrNotFound
	}
	return cloneUser(user), nil
}

// GetByEmail returns a detached copy of the user matching the normalized
// email address. Lookup is case-insensitive and ignores surrounding spaces.
func (r *UserRepository) GetByEmail(email string) (domain.User, error) {
	if r == nil {
		return domain.User{}, domain.ErrNotFound
	}
	key := domain.NormalizeEmail(email)
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.emailIndex[key]
	if !ok {
		return domain.User{}, domain.ErrNotFound
	}
	return cloneUser(r.users[id]), nil
}

// Update replaces an existing user and, atomically, updates its email index.
// A changed email must not already belong to another user.
func (r *UserRepository) Update(user domain.User) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "user repository is nil")
	}
	if user.ID == "" {
		return domain.NewError(domain.ErrorInvalid, "user id and email are required")
	}
	key, err := domain.ValidateEmail(user.Email)
	if err != nil {
		return err
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	previous, exists := r.users[user.ID]
	if !exists {
		return domain.ErrNotFound
	}
	if owner, claimed := r.emailIndex[key]; claimed && owner != user.ID {
		return domain.NewError(domain.ErrorConflict, "email already exists")
	}
	if oldKey := domain.NormalizeEmail(previous.Email); oldKey != key {
		delete(r.emailIndex, oldKey)
	}
	user.Email = key
	r.users[user.ID] = cloneUser(user)
	r.emailIndex[key] = user.ID
	return nil
}

// Delete removes a user and releases its email address.
func (r *UserRepository) Delete(id domain.UserID) error {
	if r == nil {
		return domain.ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	user, ok := r.users[id]
	if !ok {
		return domain.ErrNotFound
	}
	delete(r.users, id)
	delete(r.emailIndex, domain.NormalizeEmail(user.Email))
	return nil
}

func cloneUser(user domain.User) domain.User {
	user.PasswordMaterial = user.PasswordMaterial.Clone()
	return user
}
package domain

import (
	"net/mail"
	"strings"
	"time"
	"unicode/utf8"
)

const MinimumPasswordLength = 12

// NormalizeEmail trims surrounding whitespace and applies the canonical
// lower-case representation used for identity lookups.
func NormalizeEmail(email string) string {
	return strings.ToLower(strings.TrimSpace(email))
}

// ValidateEmail returns a normalized email address or a safe validation
// error. The original address is never included in the error message.
func ValidateEmail(email string) (string, error) {
	normalized := NormalizeEmail(email)
	if normalized == "" || strings.ContainsAny(normalized, "\r\n") {
		return "", NewError(ErrorInvalid, "invalid email address")
	}
	parsed, err := mail.ParseAddress(normalized)
	if err != nil || parsed.Address != normalized {
		return "", NewError(ErrorInvalid, "invalid email address")
	}
	return normalized, nil
}

// ValidatePassword enforces the minimum password length without ever
// including password material in the returned error.
func ValidatePassword(password string) error {
	if utf8.RuneCountInString(password) < MinimumPasswordLength {
		return NewError(ErrorInvalid, "password does not meet the minimum length")
	}
	return nil
}

// PasswordMaterial contains the derived password representation used by the
// password verifier. It deliberately has no JSON representation: password
// material is an internal authentication detail, not part of an API model.
//
// The byte slices are copied by Clone so callers do not accidentally share
// mutable credential state when a user is copied.
type PasswordMaterial struct {
	Salt       []byte `json:"-"`
	Hash       []byte `json:"-"`
	Iterations uint32 `json:"-"`
}

// Clone returns an independent copy of the password material.
func (p PasswordMaterial) Clone() PasswordMaterial {
	return PasswordMaterial{
		Salt:       append([]byte(nil), p.Salt...),
		Hash:       append([]byte(nil), p.Hash...),
		Iterations: p.Iterations,
	}
}

// PublicProfile is the safe, externally visible part of a user account.
// Password material is intentionally not present in this type.
type PublicProfile struct {
	ID            UserID    `json:"id"`
	Email         string    `json:"email"`
	EmailVerified bool      `json:"email_verified"`
	CreatedAt     time.Time `json:"created_at"`
	UpdatedAt     time.Time `json:"updated_at"`
}

// User is the complete internal user aggregate. Authentication material is
// kept separate from the public account profile and is excluded from JSON.
type User struct {
	ID               UserID           `json:"id"`
	Email            string           `json:"email"`
	EmailVerified    bool             `json:"email_verified"`
	CreatedAt        time.Time        `json:"created_at"`
	UpdatedAt        time.Time        `json:"updated_at"`
	PasswordMaterial PasswordMaterial `json:"-"`
}

// PublicProfile returns a detached profile suitable for API responses.
func (u User) PublicProfile() PublicProfile {
	return PublicProfile{
		ID:            u.ID,
		Email:         u.Email,
		EmailVerified: u.EmailVerified,
		CreatedAt:     u.CreatedAt,
		UpdatedAt:     u.UpdatedAt,
	}
}
// Package config contains the process configuration for the IAM service.
package config

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"time"
)

// Config is the configuration shared by the service dependencies.
type Config struct {
	Address               string
	Issuer                string
	HMACSecret            string
	AccessTTL             time.Duration
	RefreshTTL            time.Duration
	PasswordResetTTL      time.Duration
	EmailVerificationTTL  time.Duration
	InviteTTL             time.Duration
	ReadTimeout           time.Duration
	WriteTimeout          time.Duration
	IdleTimeout           time.Duration
	ShutdownTimeout       time.Duration
	LoginRateLimit        int
	LoginFailureThreshold int
	LoginLockDuration     time.Duration
	RegisterRateLimit     int
}

// Load reads configuration from environment variables and validates it.
func Load() (Config, error) {
	c := Config{
		Address:               envOr("IAM_ADDR", ":8080"),
		Issuer:                envOr("IAM_ISSUER", "benchmark.local/iam"),
		HMACSecret:            os.Getenv("IAM_HMAC_SECRET"),
		AccessTTL:             durationOr("IAM_ACCESS_TTL", time15Minutes),
		RefreshTTL:            durationOr("IAM_REFRESH_TTL", 30*24*time.Hour),
		PasswordResetTTL:      durationOr("IAM_PASSWORD_RESET_TTL", 15*time.Minute),
		EmailVerificationTTL:  durationOr("IAM_EMAIL_VERIFICATION_TTL", 24*time.Hour),
		InviteTTL:             durationOr("IAM_INVITE_TTL", 7*24*time.Hour),
		ReadTimeout:           durationOr("IAM_READ_TIMEOUT", 5*time.Second),
		WriteTimeout:          durationOr("IAM_WRITE_TIMEOUT", 10*time.Second),
		IdleTimeout:           durationOr("IAM_IDLE_TIMEOUT", 60*time.Second),
		ShutdownTimeout:       durationOr("IAM_SHUTDOWN_TIMEOUT", 10*time.Second),
		LoginRateLimit:        intOr("IAM_LOGIN_RATE_LIMIT", 10),
		LoginFailureThreshold: intOr("IAM_LOGIN_FAILURE_THRESHOLD", 5),
		LoginLockDuration:     durationOr("IAM_LOGIN_LOCK_DURATION", 15*time.Minute),
		RegisterRateLimit:     intOr("IAM_REGISTER_RATE_LIMIT", 5),
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

const time15Minutes = 15 * time.Minute

// Validate checks security-sensitive and server timing settings.
func (c Config) Validate() error {
	if len([]byte(c.HMACSecret)) < 32 {
		return errors.New("IAM_HMAC_SECRET must be at least 32 bytes")
	}
	if c.Address == "" {
		return errors.New("IAM_ADDR must not be empty")
	}
	if c.Issuer == "" {
		return errors.New("IAM_ISSUER must not be empty")
	}
	for name, value := range map[string]time.Duration{
		"access TTL": c.AccessTTL, "refresh TTL": c.RefreshTTL,
		"password reset TTL":     c.PasswordResetTTL,
		"email verification TTL": c.EmailVerificationTTL,
		"invite TTL":             c.InviteTTL,
		"read timeout":           c.ReadTimeout, "write timeout": c.WriteTimeout,
		"idle timeout": c.IdleTimeout, "shutdown timeout": c.ShutdownTimeout,
	} {
		if value <= 0 {
			return fmt.Errorf("%s must be greater than zero", name)
		}
	}
	if c.LoginRateLimit <= 0 || c.LoginFailureThreshold <= 0 || c.LoginLockDuration <= 0 || c.RegisterRateLimit <= 0 {
		return errors.New("rate limits must be greater than zero")
	}
	return nil
}

func envOr(name, fallback string) string {
	if value := os.Getenv(name); value != "" {
		return value
	}
	return fallback
}

func durationOr(name string, fallback time.Duration) time.Duration {
	value := os.Getenv(name)
	if value == "" {
		return fallback
	}
	parsed, err := time.ParseDuration(value)
	if err != nil {
		return -1
	}
	return parsed
}

func intOr(name string, fallback int) int {
	value := os.Getenv(name)
	if value == "" {
		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil {
		return -1
	}
	return parsed
}

