import (
	"crypto/sha256"
	"sync"
	"time"

	"benchmark.local/iam/internal/domain"
)

// InviteRepository stores only SHA-256 digests and consumes invites atomically.
type InviteRepository struct {
	mu      sync.Mutex
	invites map[[sha256.Size]byte]domain.InviteToken
}

func NewInviteRepository() *InviteRepository {
	return &InviteRepository{invites: make(map[[sha256.Size]byte]domain.InviteToken)}
}

func (r *InviteRepository) Create(invite domain.InviteToken) error {
	if r == nil || invite.OrganizationID == "" || invite.Email == "" || invite.ExpiresAt.IsZero() || len(invite.TokenHash) != sha256.Size {
		return domain.NewError(domain.ErrorInvalid, "invalid invite token")
	}
	var key [sha256.Size]byte
	copy(key[:], invite.TokenHash)
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.invites[key]; exists {
		return domain.ErrConflict
	}
	invite.TokenHash = append([]byte(nil), key[:]...)
	r.invites[key] = invite
	return nil
}

// Get returns invite metadata without exposing a raw token.
func (r *InviteRepository) Get(raw string) (domain.InviteToken, error) {
	if r == nil || raw == "" {
		return domain.InviteToken{}, domain.ErrUnauthorized
	}
	var key [sha256.Size]byte
	copy(key[:], domain.HashInviteToken(raw))
	r.mu.RLock()
	defer r.mu.RUnlock()
	invite, ok := r.invites[key]
	if !ok {
		return domain.InviteToken{}, domain.ErrUnauthorized
	}
	return invite.Clone(), nil
}

func (r *InviteRepository) Consume(raw string, now time.Time) (domain.InviteToken, error) {
	if r == nil || raw == "" {
		return domain.InviteToken{}, domain.ErrUnauthorized
	}
	var key [sha256.Size]byte
	copy(key[:], domain.HashInviteToken(raw))
	r.mu.Lock()
	defer r.mu.Unlock()
	invite, ok := r.invites[key]
	if !ok || invite.Used || !now.Before(invite.ExpiresAt) {
		return domain.InviteToken{}, domain.ErrUnauthorized
	}
	invite.Used = true
	r.invites[key] = invite
	return invite.Clone(), nil
}
package domain

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"time"
)

const InviteTokenSize = 32

// InviteToken is the 6.3 invite model. It is persisted server-side; only the
// digest is stored and the opaque bearer is never a field on this type.
type InviteToken struct {
	TokenHash      []byte         `json:"-"`
	OrganizationID OrganizationID `json:"organization_id"`
	Email          string         `json:"email"`
	Role           string         `json:"role"`
	ExpiresAt      time.Time      `json:"expires_at"`
	Used           bool           `json:"-"`
}

// MarshalJSON deliberately omits persistence and consumption state even if a
// repository value is accidentally passed to a response encoder.
func (i InviteToken) MarshalJSON() ([]byte, error) {
	type publicInvite struct {
		OrganizationID OrganizationID `json:"organization_id"`
		Email          string         `json:"email"`
		Role           string         `json:"role"`
		ExpiresAt      time.Time      `json:"expires_at"`
	}
	return json.Marshal(publicInvite{
		OrganizationID: i.OrganizationID,
		Email:          i.Email,
		Role:           i.Role,
		ExpiresAt:      i.ExpiresAt,
	})
}

// Clone returns a detached invite snapshot. In particular, callers cannot
// mutate the stored digest through a returned value.
func (i InviteToken) Clone() InviteToken {
	i.TokenHash = append([]byte(nil), i.TokenHash...)
	return i
}

func NewInviteToken() (string, error) {
	value := make([]byte, InviteTokenSize)
	if _, err := rand.Read(value); err != nil {
		return "", NewError(ErrorInvalid, "could not create invite token")
	}
	return base64.RawURLEncoding.EncodeToString(value), nil
}

func HashInviteToken(token string) []byte {
	digest := sha256.Sum256([]byte(token))
	return append([]byte(nil), digest[:]...)
}

